import{c as a,Z as o,Q as t,j as c,g as i,n as d,o as r,m as n}from"./chunks/framework.BPKcPtvA.js";const x=JSON.parse('{"title":"更新日志","description":"","frontmatter":{"title":"更新日志"},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1794895051000}'),s={name:"changelog.md"};function u(h,e,m,p,_,g){const l=o("ReleaseHistory");return t(),c("div",null,[e[0]||(e[0]=i("h1",{id:"更新日志",tabindex:"-1"},[d("更新日志 "),i("a",{class:"header-anchor",href:"#更新日志","aria-label":'Permalink to "更新日志"'},"​")],-1)),r(l),e[1]||(e[1]=n('<h2 id="_3-0-0-2026-11-15" tabindex="-1">3.0.0（2026-11-15） <a class="header-anchor" href="#_3-0-0-2026-11-15" aria-label="Permalink to &quot;3.0.0（2026-11-15）&quot;">​</a></h2><p>3.0.0 是界面与打包体系的大版本更新。启动器完整迁移到 Qt Quick / QML，原有的版本管理、资源与整合包、 服务器、联机、备份、音乐、AGENT、语音、成就、插件与基岩版能力继续保留，并统一到新的界面与交互结构中。</p><h3 id="全新-qt-quick-界面" tabindex="-1">全新 Qt Quick 界面 <a class="header-anchor" href="#全新-qt-quick-界面" aria-label="Permalink to &quot;全新 Qt Quick 界面&quot;">​</a></h3><ul><li>使用 QML 与 FluentUI 重做窗口、导航、页面、对话框与浮层。</li><li>一级导航按「游戏 / 资源与联机 / 工具与扩展」分组，支持面包屑、页面栈与 <code>fmcl://</code> 深链。</li><li>12 个功能域统一使用页面骨架与 <code>ready / loading / empty / error</code> 三态，页面、主题与语言切换不再重建整套窗口。</li><li>5 套主题、自定义强调色、版本动态主题与四语言运行时切换继续可用。</li><li>启动画面、协议与公告链条、主窗口失败兜底统一由启动控制器管理。</li></ul><h3 id="版本、资源与服务器" tabindex="-1">版本、资源与服务器 <a class="header-anchor" href="#版本、资源与服务器" aria-label="Permalink to &quot;版本、资源与服务器&quot;">​</a></h3><ul><li>原版与 8 种模组加载器安装，支持 9 种加载器识别、重命名、校验与删除。</li><li>Modrinth 与 CurseForge 双源资源浏览、依赖安装、详情页与批量更新。</li><li>六种客户端整合包安装，以及 <code>.mrpack</code> 整合包开服。</li><li>服务器安装、启动、控制台、每服独立内存、端口自动防冲突、<code>server.properties</code> 可视化编辑、服务器模组与资源包管理。</li><li>EasyTier 陶瓦联机，存档手动与自动备份、校验、恢复、导出。</li><li>基岩版 UWP / GDK 下载、安装与启动，仅支持 Windows 10 19041 及以上。</li></ul><h3 id="音乐、agent-与插件" tabindex="-1">音乐、AGENT 与插件 <a class="header-anchor" href="#音乐、agent-与插件" aria-label="Permalink to &quot;音乐、AGENT 与插件&quot;">​</a></h3><ul><li>音乐页重做：发现首页、五大在线音源与 B 站兜底、歌单、歌词、桌面歌词、播放队列与全局热键。</li><li>Windows SMTC 系统媒体控制、媒体键与进度同步。</li><li>AGENT 支持多提供商模型、33 个工具、三级权限、Skills、流式输出与工具确认。</li><li>SenseVoice 离线语音输入，支持模型下载与本地 ZIP 导入。</li><li>新增插件管理器、插件市场与 QML 页面扩展协议 <code>ui_api: 2</code>。</li><li>插件页面可登记到一级导航，通过 <code>Plugins.call</code> 取数、<code>emit_ui_event</code> 推送刷新。</li></ul><h3 id="打包与安装" tabindex="-1">打包与安装 <a class="header-anchor" href="#打包与安装" aria-label="Permalink to &quot;打包与安装&quot;">​</a></h3><ul><li>Windows 提供 x64 NSIS 安装包，按当前用户安装，无需管理员权限。</li><li>Linux 提供 x86_64 目录产物 tarball，并可通过 <code>scripts/install.sh</code> 从源码或 tarball 安装。</li><li>安装包补齐 FluentUI QML 插件 DLL，修复安装后启动时「QML 根对象未能创建」的问题。</li><li>Windows 构建日志、Linux Qt 插件定位、产物清单与 CUPS 依赖问题一并修复。</li></ul><h3 id="升级说明" tabindex="-1">升级说明 <a class="header-anchor" href="#升级说明" aria-label="Permalink to &quot;升级说明&quot;">​</a></h3><ul><li>可直接安装 3.0.0，安装目录与用户数据路径保持不变；卸载不会递归删除用户数据。</li><li>升级前建议备份 <code>config.json</code>、<code>accounts.json</code>、<code>.minecraft</code> 与音乐数据目录。</li><li>回滚方式：卸载 3.0.0 后再安装 2.12.6。</li><li>Windows 32 位不再提供 3.0.0 产物，请继续使用 2.12.6。</li><li>CustomTkinter 界面与 <code>ui_backend</code> 开关已移除，当前只提供 QML 界面；命令行模式仍在 <code>main.py</code>。</li><li>声明 <code>ui_api: 1</code> 的插件界面页面不再加载，非 UI 钩子不受影响；QML 页面请使用 <code>ui_api: 2</code> 与 <code>ui.page.register</code>。</li><li>独立 <code>FMCL-Agent.exe</code> 不再随包提供，CLI 模式使用 <code>python main.py -A</code> 或 <code>python main.py --agent &quot;指令&quot;</code>。</li></ul><h3 id="已知限制" tabindex="-1">已知限制 <a class="header-anchor" href="#已知限制" aria-label="Permalink to &quot;已知限制&quot;">​</a></h3><ul><li>macOS 暂不提供 <code>.dmg</code> 或二进制包，只支持从源码运行。</li><li>Linux 目前只提供 x86_64 产物，暂无 ARM64 二进制。</li><li>Linux 非 root 环境下全局热键可能不可用，不影响其他功能。</li><li>在线音乐与资源搜索依赖第三方接口，接口变动或网络限制可能导致个别来源暂时不可用。</li><li>GDK 基岩版首次使用可能需要 .NET 10 SDK，精简版安装包不内置 SDK。</li></ul>',14))])}const b=a(s,[["render",u]]);export{x as __pageData,b as default};
